INSERT INTO poems (
    poet_id,
    title,
    text,
    source
) VALUES (
    @poet_id,
    'Altyň biri',
    'Bir şahada alty nara.
Meňzäp duran alty jora
Işden gelip agşamara,
Guýudan suw çekip gitdi.

Aklym aldy altyň biri,
Her bakyşy derde däri.
Ýüregimde şondan bäri
Yşk ataşyn ýakyp gitdi.

Suw diledim agzym gurap,
«Içiň!» diýdi ýygryljyrap.
Içdim gyza ogryn garap,
Suw ýakamdan akyp gitdi.

Has dogumly, has berdaşly,
On sekiz – on dokuz ýaşly.
Gülýakasy tylla gaşly
Ýyldyrym dek çakyp gitdi.

Söýenimi aňlamady,
Ýa aňsa-da geňlemedi.
Diýjek sözüm diňlemedi,
Gözün-gaşyn kakyp gitdi.

Belki onuň ýary bardyr,
Bir görmäge zary bardyr.
Ýa-da mende ary bardyr,
Ýüregimi ýakyp gitdi.
Bogun-bogun söküp gitdi.

           280               ',
    ''
);

INSERT INTO poems (
    poet_id,
