INSERT INTO poems (
    poet_id,
    title,
    text,
    source
) VALUES (
    @poet_id,
    'Adamyň ömri hakynda oýun gatyşykly çyn',
    'Bebele öýkünibräk
        On ýaşyňda owlaksyň sen,
        On bäşiňde – toklusyň.
        Bökmäge-de haklysyň sen,
        Ýatmaga-da haklysyň.

        Ýigrimide kürresiň sen,
        Ýigrimbäşde atsyň sen.
        Otuz-kyrkda çyn bedewsiň,
        Elliňde-de itsiň sen:

                    386                   
          Hem-ä hilegärsiň sen,
          Hemem akyllysyň sen.
          Duşman üçin ýaraksyň,
          Dosta ýakymlysyň sen.

          Altmyş, ýetmiş, segsen, togsan
          Bular özüňe bagly.
          Gaplaňam bolup bilersiň,
          Möjegem bolup bilersiň,
          Şagalam bolup bilersiň,
          Doňuzam bolup bilersiň,
          Bolsaň-da adam ogly.

          Ýüze ýeteniňde weli
          Borsuň ütülen towuk.
          Ketegiň içem sowuk,
          Ketegiň daşam sowuk.
          Emma özüň adam bolsaň –
          Ýokdur ullakan howp.

          Iliň-günüň, dost-ýaryň
          Seni horlamaz, garaz.
          «Ütülen towuk» diýip,
          Azaram berip durmaz.
          Gaty gitse, diýerler:
          «Ganatsyz, garry horaz!»',
    ''
);

